import { useCallback, useEffect, useMemo, useState, type FormEvent } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Activity, Bell, CalendarDays, Check, CheckCheck, CircleAlert,
  ClipboardList, Clock3, FilePlus2, FileText, Flag, FolderKanban, Inbox, Mail, MessageCircle,
  Paperclip, Plus, RefreshCw, Search, Send, ShieldCheck, Sparkles,
  Users, X,
} from 'lucide-react';
import { Button, Card, LoadingCard } from '@/components/ui';
import { useAuth } from '@/contexts/AuthContext';
import {
  MarketingService, type MarketingMember, type MarketingMilestone, type MarketingProject, type MarketingPriority,
  type MarketingStatus, type MarketingTask, type MarketingWorkspaceData,
} from '@/services/marketing-service';

type View = 'overview' | 'projects' | 'tasks' | 'inbox' | 'team' | 'reports';
const statusLabels: Record<MarketingStatus, string> = {
  nao_iniciado: 'Não iniciado', briefing_pendente: 'Briefing pendente', pronto: 'Pronto para execução', em_andamento: 'Em andamento',
  aguardando_informacoes: 'Aguardando informações', em_revisao: 'Em revisão', aguardando_aprovacao: 'Aguardando aprovação',
  ajustes_solicitados: 'Ajustes solicitados', aprovado: 'Aprovado', concluido: 'Concluído', pausado: 'Pausado', cancelado: 'Cancelado',
};
const priorityLabels: Record<MarketingPriority, string> = { baixa: 'Baixa', normal: 'Normal', alta: 'Alta', urgente: 'Urgente' };
const roles = [
  { value: 'admin', label: 'Administrador' }, { value: 'gestor', label: 'Gestor de projetos' },
  { value: 'desenvolvedor', label: 'Desenvolvedor' }, { value: 'designer', label: 'Designer' },
  { value: 'copywriter', label: 'Copywriter' }, { value: 'trafego', label: 'Tráfego' },
] as const;
const views: Array<{ id: View; label: string; icon: typeof Activity }> = [
  { id: 'overview', label: 'Visão geral', icon: Activity }, { id: 'projects', label: 'Projetos', icon: FolderKanban },
  { id: 'tasks', label: 'Tarefas', icon: ClipboardList }, { id: 'inbox', label: 'Caixa de entrada', icon: Inbox },
  { id: 'team', label: 'Equipe', icon: Users }, { id: 'reports', label: 'Relatórios', icon: CalendarDays },
];
const emptyWorkspace: MarketingWorkspaceData = { member: null, members: [], projects: [], tasks: [], projectMembers: [], notifications: [], canManage: false, canManageTeam: false, canManageTasks: false, canUpdateTasks: false, canManageReviews: false, canRequestReviews: false, canManageFiles: false, canUploadFiles: false, canComment: false, canSendMessages: false, canViewReports: false };

function localDate(value: string | null | undefined) {
  if (!value) return 'Sem prazo';
  const date = new Date(`${value.slice(0, 10)}T12:00:00`);
  return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'medium' }).format(date);
}
function relativeTime(value: string) {
  return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value));
}
function isLate(value: string | null, status: string) {
  return Boolean(value && status !== 'concluido' && new Date(`${value.slice(0, 10)}T23:59:59`) < new Date());
}
function cls(...items: Array<string | false | null | undefined>) { return items.filter(Boolean).join(' '); }
function statusClass(status: string) {
  if (status === 'concluido' || status === 'aprovado') return 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-300';
  if (status === 'cancelado' || status === 'pausado' || status === 'ajustes_solicitados') return 'bg-rose-500/10 text-rose-700 dark:text-rose-300';
  if (status === 'em_andamento' || status === 'pronto') return 'bg-sky-500/10 text-sky-700 dark:text-sky-300';
  if (status === 'aguardando_aprovacao' || status === 'em_revisao' || status === 'aguardando_informacoes') return 'bg-amber-500/10 text-amber-700 dark:text-amber-300';
  return 'bg-bg-tertiary text-text-secondary';
}
function FormField({ label, ...props }: React.InputHTMLAttributes<HTMLInputElement> & { label: string }) {
  return <label className="grid gap-1.5 text-xs font-medium text-text-secondary">{label}<input {...props} className={cls('min-h-10 rounded-xl border border-border-color bg-bg-secondary px-3 text-sm text-text-primary outline-none focus:ring-2 focus:ring-brand/50', props.className)} /></label>;
}
function FormSelect({ label, children, ...props }: React.SelectHTMLAttributes<HTMLSelectElement> & { label: string; children: React.ReactNode }) {
  return <label className="grid gap-1.5 text-xs font-medium text-text-secondary">{label}<select {...props} className={cls('min-h-10 rounded-xl border border-border-color bg-bg-secondary px-3 text-sm text-text-primary outline-none focus:ring-2 focus:ring-brand/50', props.className)}>{children}</select></label>;
}
function StatusPill({ value }: { value: string }) { return <span className={cls('inline-flex w-fit items-center rounded-full px-2.5 py-1 text-[11px] font-semibold', statusClass(value))}>{statusLabels[value as MarketingStatus] || value}</span>; }
function PriorityPill({ value }: { value: string }) {
  const level = value === 'urgente' ? 'text-rose-600 bg-rose-500/10' : value === 'alta' ? 'text-orange-700 bg-orange-500/10' : 'text-text-secondary bg-bg-tertiary';
  return <span className={cls('inline-flex rounded-full px-2 py-1 text-[11px] font-semibold', level)}>{priorityLabels[value as MarketingPriority] || value}</span>;
}

export default function MarketingWorkspace() {
  const { user, isLoading: authLoading } = useAuth();
  const navigate = useNavigate();
  const [data, setData] = useState<MarketingWorkspaceData>(emptyWorkspace);
  const [loading, setLoading] = useState(true);
  const [authorized, setAuthorized] = useState<boolean | null>(null);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [view, setView] = useState<View>('overview');
  const [query, setQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('todos');
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [showNewProject, setShowNewProject] = useState(false);
  const [showNewTask, setShowNewTask] = useState(false);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async (quiet = false) => {
    if (!user) return;
    if (!quiet) setLoading(true);
    try {
      setError('');
      const next = await MarketingService.loadWorkspace();
      setData(next);
      setAuthorized(true);
      setSelectedProjectId((current) => current && next.projects.some((project) => project.id === current) ? current : next.projects[0]?.id || null);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : 'Não foi possível carregar a Central de Marketing.');
    } finally { setLoading(false); }
  }, [user]);

  useEffect(() => {
    if (authLoading) return;
    if (!user) { setAuthorized(false); setLoading(false); return; }
    let alive = true;
    void MarketingService.isAuthorized().then((value) => { if (alive) { setAuthorized(value); if (value) void load(); else setLoading(false); } }).catch((cause) => { if (alive) { setError(cause instanceof Error ? cause.message : 'Falha ao validar acesso.'); setAuthorized(false); setLoading(false); } });
    return () => { alive = false; };
  }, [authLoading, user, load]);

  useEffect(() => {
    if (!user || authorized !== true) return;
    return MarketingService.subscribe(() => { void load(true); });
  }, [authorized, load, user]);

  const selectedProject = data.projects.find((project) => project.id === selectedProjectId) || null;
  const ownProjectIds = new Set(data.projectMembers.filter((membership) => membership.user_id === user?.id).map((membership) => membership.project_id));
  const visibleProjects = useMemo(() => data.projects.filter((project) => {
    const memberCanSee = data.canManage || project.owner_id === user?.id || ownProjectIds.has(project.id);
    const matchesQuery = !query.trim() || `${project.name} ${project.code || ''} ${project.client_label || ''}`.toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'));
    return memberCanSee && matchesQuery && (statusFilter === 'todos' || project.status === statusFilter);
  }), [data.canManage, data.projects, ownProjectIds, query, statusFilter, user?.id]);
  const visibleTasks = useMemo(() => data.tasks.filter((task) => {
    const own = task.assignee_id === user?.id || ownProjectIds.has(task.project_id);
    const permitted = data.canManage || own;
    const matchesQuery = !query.trim() || `${task.title} ${task.description}`.toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'));
    const filterStatus = statusFilter === 'todos' || task.status === statusFilter;
    return permitted && matchesQuery && filterStatus;
  }), [data.canManage, data.tasks, ownProjectIds, query, statusFilter, user?.id]);
  const metrics = useMemo(() => ({
    activeProjects: data.projects.filter((project) => !['concluido', 'cancelado'].includes(project.status)).length,
    overdueTasks: visibleTasks.filter((task) => isLate(task.due_at, task.status)).length,
    inReview: visibleTasks.filter((task) => ['em_revisao', 'aguardando_aprovacao'].includes(task.status)).length,
    done: visibleTasks.filter((task) => task.status === 'concluido').length,
  }), [data.projects, visibleTasks]);

  const runAction = async (action: () => Promise<void>, message: string) => {
    setBusy(true); setNotice(''); setError('');
    try { await action(); setNotice(message); await load(true); }
    catch (cause) { setError(cause instanceof Error ? cause.message : 'Não foi possível concluir a operação.'); }
    finally { setBusy(false); }
  };

  if (authLoading || loading) return <div className="mx-auto max-w-7xl p-6"><LoadingCard message="Abrindo a Central de Marketing…" /></div>;
  if (!user) return <div className="mx-auto max-w-lg p-6"><Card><p className="font-semibold">Entre no GrowMoney para continuar.</p><Button className="mt-4" onClick={() => navigate('/auth')}>Entrar</Button></Card></div>;
  if (authorized === false) return <div className="mx-auto max-w-xl p-6"><Card><div className="flex items-start gap-3"><ShieldCheck className="mt-0.5 h-6 w-6 text-brand" /><div><h1 className="text-lg font-bold text-text-primary">Acesso restrito à equipe</h1><p className="mt-1 text-sm text-text-secondary">Sua conta ainda não foi autorizada para a Central de Marketing. Fale com o administrador da plataforma.</p><Button className="mt-4" variant="outline" onClick={() => navigate('/dashboard')}>Voltar ao sistema</Button></div></div></Card></div>;

  return (
    <main className="mx-auto w-full max-w-[1500px] px-3 py-5 sm:px-6 sm:py-7">
      <header className="mb-6 flex flex-wrap items-start justify-between gap-4">
        <div><p className="text-xs font-semibold uppercase tracking-[0.18em] text-brand">Operação da agência</p><h1 className="mt-1 text-2xl font-bold tracking-tight text-text-primary sm:text-3xl">Equipe de Marketing</h1><p className="mt-1 max-w-2xl text-sm text-text-secondary">Projetos, tarefas, comunicação e aprovações em um espaço de trabalho compartilhado.</p></div>
        <div className="flex flex-wrap items-center gap-2">
          <Button variant="outline" onClick={() => void load()} leftIcon={<RefreshCw className="h-4 w-4" />}>Atualizar</Button>
          {data.canManage && <Button onClick={() => setShowNewProject(true)} leftIcon={<Plus className="h-4 w-4" />}>Novo projeto</Button>}
        </div>
      </header>

      {(error || notice) && <div role={error ? 'alert' : 'status'} className={cls('mb-4 rounded-xl border px-4 py-3 text-sm', error ? 'border-rose-500/30 bg-rose-500/5 text-rose-700 dark:text-rose-300' : 'border-emerald-500/30 bg-emerald-500/5 text-emerald-700 dark:text-emerald-300')}>{error || notice}</div>}

      <div className="mb-5 flex flex-col gap-3 rounded-2xl border border-border-color bg-bg-primary p-2 sm:flex-row sm:items-center sm:justify-between">
        <nav aria-label="Seções da equipe de marketing" className="flex gap-1 overflow-x-auto">
          {views.filter((item) => (item.id !== 'team' || data.canManageTeam) && (item.id !== 'reports' || data.canViewReports)).map((item) => <button key={item.id} type="button" onClick={() => setView(item.id)} className={cls('inline-flex min-h-10 shrink-0 items-center gap-2 rounded-xl px-3 text-sm font-medium transition-colors', view === item.id ? 'bg-brand/15 text-brand' : 'text-text-secondary hover:bg-bg-tertiary')}><item.icon className="h-4 w-4" />{item.label}{item.id === 'inbox' && data.notifications.some((item) => !item.read_at) && <span className="h-2 w-2 rounded-full bg-brand" />}</button>)}
        </nav>
        <div className="flex gap-2 px-1 sm:w-80"><label className="relative min-w-0 flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-text-secondary" /><input aria-label="Pesquisar projetos e tarefas" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Pesquisar projetos e tarefas" className="min-h-10 w-full rounded-xl border border-border-color bg-bg-secondary pl-9 pr-3 text-sm text-text-primary outline-none focus:ring-2 focus:ring-brand/50" /></label><select aria-label="Filtrar por status" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)} className="w-32 rounded-xl border border-border-color bg-bg-secondary px-2 text-xs text-text-primary"><option value="todos">Todos status</option>{Object.entries(statusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div>
      </div>

      {view === 'overview' && <Overview data={data} tasks={visibleTasks} projects={visibleProjects} metrics={metrics} onOpenProject={(id) => { setSelectedProjectId(id); setView('projects'); }} onOpenTask={(id) => { const task = data.tasks.find((item) => item.id === id); if (task) setSelectedProjectId(task.project_id); setView('tasks'); }} />}
      {view === 'projects' && <ProjectsPanel projects={visibleProjects} tasks={data.tasks} projectMembers={data.projectMembers} members={data.members} selected={selectedProject} canManage={data.canManage} canManageTeam={data.canManageTeam} canManageTasks={data.canManageTasks} canUpdateTasks={data.canUpdateTasks} canManageReviews={data.canManageReviews} canRequestReviews={data.canRequestReviews} canManageFiles={data.canManageFiles} canUploadFiles={data.canUploadFiles} canComment={data.canComment} canSendMessages={data.canSendMessages} busy={busy} onSelect={(id) => setSelectedProjectId(id)} onCreate={() => setShowNewProject(true)} onEdit={(id, patch) => runAction(() => MarketingService.updateProject(id, patch).then(() => undefined), 'Projeto atualizado.')} onAddTask={(id) => { setSelectedProjectId(id); setShowNewTask(true); }} onAssign={(projectId, userId, assigned) => runAction(() => MarketingService.assignProjectMember(projectId, userId, assigned), 'Equipe do projeto atualizada.')} onRefresh={() => void load(true)} />}
      {view === 'tasks' && <TasksPanel tasks={visibleTasks} projects={data.projects} members={data.members} canManage={data.canManageTasks} canUpdateTasks={data.canUpdateTasks} canComment={data.canComment} canRequestReviews={data.canRequestReviews} currentUserId={user.id} onUpdate={(id, patch) => runAction(() => MarketingService.updateTask(id, patch).then(() => undefined), 'Tarefa atualizada.')} onComment={(id, body) => runAction(() => MarketingService.addComment(id, body), 'Comentário adicionado.')} onReview={(projectId, taskId, reviewerId) => runAction(() => MarketingService.requestApproval(projectId, taskId, reviewerId), 'Solicitação de revisão enviada.')} />}
      {view === 'inbox' && <InboxPanel notifications={data.notifications} onMarkRead={(id) => runAction(() => MarketingService.markNotificationRead(id), 'Notificação marcada como lida.')} />}
      {view === 'team' && data.canManageTeam && <TeamPanel members={data.members} currentUserId={user.id} onSave={(userId, nome, email, role, active, overrides) => runAction(() => MarketingService.upsertMember(userId, nome, email, role, active, overrides), 'Integrante atualizado.')} onInvite={(nome, email, role) => runAction(async () => { await MarketingService.inviteMember({ nome, email, role }); }, 'Convite enviado. O profissional receberá o link para confirmar o e-mail e definir a senha.')} />}
      {view === 'reports' && <ReportsPanel data={data} tasks={visibleTasks} />}

      {showNewProject && <NewProjectModal members={data.members.filter((member) => member.status === 'active')} onClose={() => setShowNewProject(false)} onSubmit={(input, memberIds) => runAction(async () => { const project = await MarketingService.createProject(input, memberIds); setSelectedProjectId(project.id); setView('projects'); setShowNewProject(false); }, 'Projeto criado e equipe atribuída.')} />}
      {showNewTask && selectedProject && <NewTaskModal project={selectedProject} members={data.members.filter((member) => member.status === 'active')} onClose={() => setShowNewTask(false)} onSubmit={(input) => runAction(async () => { await MarketingService.createTask(input); setShowNewTask(false); }, 'Tarefa criada.')} />}
    </main>
  );
}

function Overview({ data, tasks, projects, metrics, onOpenProject, onOpenTask }: { data: MarketingWorkspaceData; tasks: MarketingTask[]; projects: MarketingProject[]; metrics: { activeProjects: number; overdueTasks: number; inReview: number; done: number }; onOpenProject: (id: string) => void; onOpenTask: (id: string) => void }) {
  const cards = [
    { label: 'Projetos ativos', value: metrics.activeProjects, icon: FolderKanban, hint: 'com acesso autorizado' },
    { label: 'Minhas tarefas', value: tasks.filter((task) => task.assignee_id === data.member?.user_id && task.status !== 'concluido').length, icon: ClipboardList, hint: 'atribuídas a você' },
    { label: 'Atrasadas', value: metrics.overdueTasks, icon: CircleAlert, hint: 'precisam de atenção' },
    { label: 'Em revisão', value: metrics.inReview, icon: CheckCheck, hint: `${metrics.done} concluídas` },
  ];
  const assignedTasks = tasks.filter((task) => task.assignee_id === data.member?.user_id && task.status !== 'concluido').slice(0, 6);
  const recentProjects = [...projects].sort((a, b) => b.updated_at.localeCompare(a.updated_at)).slice(0, 5);
  return <div className="grid gap-4 xl:grid-cols-[minmax(0,1.45fr)_minmax(300px,.8fr)]">
    <div className="grid gap-3 sm:grid-cols-2 xl:col-span-2 xl:grid-cols-4">{cards.map((card) => <Card key={card.label} padding="md"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-text-secondary">{card.label}</p><p className="mt-2 text-3xl font-bold tabular-nums text-text-primary">{card.value}</p><p className="mt-1 text-[11px] text-text-secondary">{card.hint}</p></div><span className="rounded-xl bg-brand/10 p-2.5 text-brand"><card.icon className="h-5 w-5" /></span></div></Card>)}</div>
    <Card header={<div className="flex items-center justify-between"><h2 className="font-semibold text-text-primary">Minhas próximas tarefas</h2><span className="text-xs text-text-secondary">{assignedTasks.length} pendentes</span></div>}><div className="space-y-2">{assignedTasks.length ? assignedTasks.map((task) => <button key={task.id} type="button" onClick={() => onOpenTask(task.id)} className="flex w-full items-center justify-between gap-3 rounded-xl border border-border-color p-3 text-left hover:border-brand/50"><span className="min-w-0"><span className="block truncate text-sm font-semibold text-text-primary">{task.title}</span><span className="mt-1 block text-xs text-text-secondary">Prazo: {localDate(task.due_at)}</span></span><span className="shrink-0"><PriorityPill value={task.priority} /></span></button>) : <EmptyState icon={Check} title="Sem tarefas atribuídas" detail="Quando uma tarefa for atribuída a você, ela aparecerá aqui." />}</div></Card>
    <Card header={<div className="flex items-center justify-between"><h2 className="font-semibold text-text-primary">Projetos recentes</h2><span className="text-xs text-text-secondary">{projects.length} no seu escopo</span></div>}><div className="space-y-2">{recentProjects.length ? recentProjects.map((project) => <button key={project.id} type="button" onClick={() => onOpenProject(project.id)} className="flex w-full items-center justify-between gap-3 rounded-xl border border-border-color p-3 text-left hover:border-brand/50"><span className="min-w-0"><span className="block truncate text-sm font-semibold text-text-primary">{project.name}</span><span className="mt-1 block text-xs text-text-secondary">{project.client_label || 'Projeto interno'} · atualizado {relativeTime(project.updated_at)}</span></span><StatusPill value={project.status} /></button>) : <EmptyState icon={FolderKanban} title="Nenhum projeto disponível" detail="Os projetos atribuídos aparecerão aqui." />}</div></Card>
    <Card className="xl:col-span-2" header={<div className="flex items-center gap-2"><Sparkles className="h-4 w-4 text-brand" /><h2 className="font-semibold text-text-primary">Atividade e prazos próximos</h2></div>}><div className="grid gap-3 sm:grid-cols-2">{tasks.filter((task) => task.due_at && task.status !== 'concluido').sort((a, b) => (a.due_at || '').localeCompare(b.due_at || '')).slice(0, 8).map((task) => <div key={task.id} className="flex items-center gap-3 rounded-xl bg-bg-secondary p-3"><Clock3 className={cls('h-4 w-4 shrink-0', isLate(task.due_at, task.status) ? 'text-rose-500' : 'text-brand')} /><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium text-text-primary">{task.title}</p><p className="text-xs text-text-secondary">{localDate(task.due_at)} · {projects.find((project) => project.id === task.project_id)?.name || 'Projeto'}</p></div>{isLate(task.due_at, task.status) && <span className="text-[10px] font-bold uppercase text-rose-600">Atraso</span>}</div>)}{!tasks.some((task) => task.due_at && task.status !== 'concluido') && <p className="text-sm text-text-secondary">Nenhum prazo futuro cadastrado.</p>}</div></Card>
  </div>;
}

function ProjectsPanel({ projects, tasks, projectMembers, members, selected, canManage, canManageTeam, canManageTasks, canUpdateTasks, canManageReviews, canRequestReviews, canManageFiles, canUploadFiles, canComment, canSendMessages, busy, onSelect, onCreate, onEdit, onAddTask, onAssign, onRefresh }: { projects: MarketingProject[]; tasks: MarketingTask[]; projectMembers: MarketingWorkspaceData['projectMembers']; members: MarketingMember[]; selected: MarketingProject | null; canManage: boolean; canManageTeam: boolean; canManageTasks: boolean; canUpdateTasks: boolean; canManageReviews: boolean; canRequestReviews: boolean; canManageFiles: boolean; canUploadFiles: boolean; canComment: boolean; canSendMessages: boolean; busy: boolean; onSelect: (id: string) => void; onCreate: () => void; onEdit: (id: string, patch: Partial<MarketingProject>) => void; onAddTask: (id: string) => void; onAssign: (projectId: string, userId: string, assigned: boolean) => void; onRefresh: () => void }) {
  const [layout, setLayout] = useState<'list' | 'kanban' | 'calendar'>('list');
  return <div className="grid gap-4 lg:grid-cols-[minmax(240px,.7fr)_minmax(0,1.6fr)]">
    <Card padding="sm" className="h-fit"><div className="flex items-center justify-between p-2"><div><h2 className="font-semibold text-text-primary">Projetos</h2><p className="mt-0.5 text-xs text-text-secondary">{projects.length} encontrados</p></div>{canManage && <button type="button" aria-label="Novo projeto" onClick={onCreate} className="rounded-lg p-2 text-brand hover:bg-brand/10"><Plus className="h-4 w-4" /></button>}</div><div className="space-y-1">{projects.map((project) => { const projectTasks = tasks.filter((task) => task.project_id === project.id); const progress = projectTasks.length ? Math.round(projectTasks.reduce((total, task) => total + task.progress, 0) / projectTasks.length) : 0; return <button key={project.id} type="button" onClick={() => onSelect(project.id)} className={cls('w-full rounded-xl border p-3 text-left transition-colors', selected?.id === project.id ? 'border-brand bg-brand/5' : 'border-transparent hover:bg-bg-secondary')}><span className="flex items-center justify-between gap-2"><span className="truncate text-sm font-semibold text-text-primary">{project.name}</span><PriorityPill value={project.priority} /></span><span className="mt-1 block truncate text-xs text-text-secondary">{project.client_label || 'Projeto interno'} · prazo {localDate(project.due_at)}</span><span className="mt-2 block h-1.5 overflow-hidden rounded-full bg-bg-tertiary"><span className="block h-full rounded-full bg-brand" style={{ width: `${progress}%` }} /></span><span className="mt-1 block text-[10px] text-text-secondary">{projectTasks.length} tarefas · {progress}% concluído</span></button>; })}{!projects.length && <EmptyState icon={FolderKanban} title="Nenhum projeto encontrado" detail={canManage ? 'Crie o primeiro projeto de marketing.' : 'Quando adicionarem você a um projeto, ele aparecerá aqui.'} />}</div></Card>
    {selected ? <ProjectDetail project={selected} tasks={tasks.filter((task) => task.project_id === selected.id)} projectMembers={projectMembers.filter((member) => member.project_id === selected.id)} members={members} canManage={canManage} canManageTeam={canManageTeam} canManageTasks={canManageTasks} canUpdateTasks={canUpdateTasks} canManageReviews={canManageReviews} canRequestReviews={canRequestReviews} canManageFiles={canManageFiles} canUploadFiles={canUploadFiles} canComment={canComment} canSendMessages={canSendMessages} busy={busy} layout={layout} setLayout={setLayout} onEdit={(patch) => onEdit(selected.id, patch)} onAddTask={() => onAddTask(selected.id)} onAssign={(userId, assigned) => onAssign(selected.id, userId, assigned)} onRefresh={onRefresh} /> : <Card><EmptyState icon={FolderKanban} title="Selecione um projeto" detail="Briefing, tarefas, conversas e arquivos aparecerão aqui." /></Card>}
  </div>;
}

function ProjectDetail({ project, tasks, projectMembers, members, canManage, canManageTeam, canManageTasks, canUpdateTasks, canManageReviews, canRequestReviews, canManageFiles, canUploadFiles, canComment, canSendMessages, busy, layout, setLayout, onEdit, onAddTask, onAssign, onRefresh }: { project: MarketingProject; tasks: MarketingTask[]; projectMembers: MarketingWorkspaceData['projectMembers']; members: MarketingMember[]; canManage: boolean; canManageTeam: boolean; canManageTasks: boolean; canUpdateTasks: boolean; canManageReviews: boolean; canRequestReviews: boolean; canManageFiles: boolean; canUploadFiles: boolean; canComment: boolean; canSendMessages: boolean; busy: boolean; layout: 'list' | 'kanban' | 'calendar'; setLayout: (layout: 'list' | 'kanban' | 'calendar') => void; onEdit: (patch: Partial<MarketingProject>) => void; onAddTask: () => void; onAssign: (userId: string, assigned: boolean) => void; onRefresh: () => void }) {
  const { user } = useAuth();
  const [tab, setTab] = useState<'overview' | 'brief' | 'files' | 'chat' | 'reviews' | 'history'>('overview');
  const [brief, setBrief] = useState<Record<string, unknown> | null>(null);
  const [fileRows, setFileRows] = useState<Array<Record<string, any>>>([]);
  const [approvals, setApprovals] = useState<Array<Record<string, any>>>([]);
  const [events, setEvents] = useState<Array<Record<string, any>>>([]);
  const [milestones, setMilestones] = useState<MarketingMilestone[]>([]);
  const [localError, setLocalError] = useState('');
  const [localNotice, setLocalNotice] = useState('');
  const [busyLocal, setBusyLocal] = useState(false);
  const [briefEditing, setBriefEditing] = useState(false);
  const tabs = ['overview', 'brief', 'files', 'chat', 'reviews', 'history'] as const;
  const refreshDetail = useCallback(async () => {
    try {
      const [latestBrief, files, reviews, history, projectMilestones] = await Promise.all([MarketingService.loadBrief(project.id), MarketingService.projectFiles(project.id), MarketingService.approvals(project.id), MarketingService.projectEvents(project.id), MarketingService.milestones(project.id)]);
      setBrief(latestBrief?.content || {}); setFileRows(files); setApprovals(reviews); setEvents(history); setMilestones(projectMilestones);
    } catch (cause) { setLocalError(cause instanceof Error ? cause.message : 'Falha ao atualizar projeto.'); }
  }, [project.id]);
  useEffect(() => { void refreshDetail(); }, [refreshDetail]);
  const membersById = new Map(members.map((member) => [member.user_id, member]));
  const assignedIds = new Set(projectMembers.map((member) => member.user_id));
  const projectProgress = tasks.length ? Math.round(tasks.reduce((sum, task) => sum + task.progress, 0) / tasks.length) : 0;
  const labels: Record<typeof tabs[number], string> = { overview: 'Visão geral', brief: 'Briefing', files: 'Arquivos', chat: 'Chat', reviews: 'Revisões', history: 'Histórico' };
  const update = async (work: () => Promise<unknown>, message: string) => { setBusyLocal(true); setLocalError(''); setLocalNotice(''); try { await work(); await refreshDetail(); onRefresh(); setLocalNotice(message); } catch (cause) { setLocalError(cause instanceof Error ? cause.message : 'Falha na operação.'); } finally { setBusyLocal(false); } };
  const onUpload = async (file: File, category: string) => { await update(() => MarketingService.uploadFile(project.id, file, category), 'Arquivo armazenado no servidor da hospedagem.'); };
  return <Card padding="none" className="min-w-0 overflow-hidden">
    <div className="border-b border-border-color p-4 sm:p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h2 className="max-w-full truncate text-xl font-bold text-text-primary">{project.name}</h2><StatusPill value={project.status} /></div><p className="mt-1 text-sm text-text-secondary">{project.client_label || 'Projeto interno'}{project.code ? ` · ${project.code}` : ''}</p></div><div className="flex items-center gap-2"><PriorityPill value={project.priority} />{canManage && <select aria-label="Alterar status do projeto" value={project.status} disabled={busy || busyLocal} onChange={(event) => onEdit({ status: event.target.value as MarketingStatus })} className="min-h-9 rounded-lg border border-border-color bg-bg-secondary px-2 text-xs text-text-primary">{Object.entries(statusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select>}</div></div>
      <div className="mt-4 grid gap-3 sm:grid-cols-[1fr_1fr_auto]"><div><div className="flex justify-between text-xs"><span className="text-text-secondary">Progresso das tarefas</span><strong className="text-text-primary">{projectProgress}%</strong></div><div className="mt-1.5 h-2 rounded-full bg-bg-tertiary"><div className="h-2 rounded-full bg-brand transition-all" style={{ width: `${projectProgress}%` }} /></div></div><div className="text-xs"><span className="block text-text-secondary">Prazo final</span><strong className={cls('mt-1 block', isLate(project.due_at, project.status) ? 'text-rose-600' : 'text-text-primary')}>{localDate(project.due_at)}</strong></div><div className="flex items-end"><Button size="sm" variant="outline" onClick={() => void refreshDetail()} leftIcon={<RefreshCw className="h-3.5 w-3.5" />}>Sincronizar</Button></div></div>
      <div className="mt-4 flex gap-1 overflow-x-auto">{tabs.map((item) => <button key={item} type="button" onClick={() => setTab(item)} className={cls('min-h-9 shrink-0 rounded-lg px-3 text-xs font-semibold', tab === item ? 'bg-brand/15 text-brand' : 'text-text-secondary hover:bg-bg-tertiary')}>{labels[item]}</button>)}</div>
    </div>
    {localError && <div className="mx-4 mt-3 rounded-lg bg-rose-500/10 px-3 py-2 text-xs text-rose-700" role="alert">{localError}</div>}
    {localNotice && <div className="mx-4 mt-3 rounded-lg bg-emerald-500/10 px-3 py-2 text-xs text-emerald-700" role="status">{localNotice}</div>}
    <div className="p-4 sm:p-5">
      {tab === 'overview' && <div className="space-y-5">
        <div className="grid gap-3 md:grid-cols-2"><div className="rounded-xl bg-bg-secondary p-4"><h3 className="text-xs font-semibold uppercase tracking-wide text-text-secondary">Objetivo</h3><p className="mt-2 whitespace-pre-wrap text-sm text-text-primary">{project.objective || 'Defina o objetivo do projeto.'}</p></div><div className="rounded-xl bg-bg-secondary p-4"><h3 className="text-xs font-semibold uppercase tracking-wide text-text-secondary">Escopo e resultados</h3><p className="mt-2 whitespace-pre-wrap text-sm text-text-primary">{project.scope || project.description || 'Descreva escopo, entregáveis e critérios de aceite.'}</p></div></div>
        <MilestonesPanel milestones={milestones} members={members} canManage={canManageTasks} onCreate={(title, dueAt, assigneeId) => void update(() => MarketingService.createMilestone(project.id, title, dueAt, assigneeId), 'Marco adicionado ao cronograma.')} onToggle={(milestone) => void update(() => MarketingService.updateMilestone(milestone.id, { completed_at: milestone.completed_at ? null : new Date().toISOString() }), milestone.completed_at ? 'Marco reaberto.' : 'Marco concluído.')} />
        <div><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><div><h3 className="font-semibold text-text-primary">Etapas e tarefas</h3><p className="mt-0.5 text-xs text-text-secondary">{tasks.filter((task) => task.status === 'concluido').length} de {tasks.length} concluídas</p></div><div className="flex items-center gap-2"><select value={layout} onChange={(event) => setLayout(event.target.value as typeof layout)} aria-label="Visualização de tarefas" className="min-h-9 rounded-lg border border-border-color bg-bg-secondary px-2 text-xs text-text-primary"><option value="list">Lista</option><option value="kanban">Quadro</option><option value="calendar">Prazos</option></select>{canManageTasks && <Button size="sm" onClick={onAddTask} leftIcon={<Plus className="h-3.5 w-3.5" />}>Nova tarefa</Button>}</div></div>
          {layout === 'kanban' ? <div className="grid gap-3 md:grid-cols-3">{(['nao_iniciado','em_andamento','em_revisao','concluido'] as MarketingStatus[]).map((status) => <div key={status} className="rounded-xl bg-bg-secondary p-3"><div className="mb-2 flex items-center justify-between"><StatusPill value={status} /><span className="text-[10px] text-text-secondary">{tasks.filter((task) => task.status === status).length}</span></div><div className="space-y-2">{tasks.filter((task) => task.status === status).map((task) => <TaskCard key={task.id} task={task} members={membersById} canUpdate={canUpdateTasks && (canManageTasks || task.assignee_id === user?.id)} canComment={canComment} onUpdate={(patch) => void update(() => MarketingService.updateTask(task.id, patch), 'Tarefa atualizada.')} />)}</div></div>)}</div> : layout === 'calendar' ? <TaskCalendar tasks={tasks} members={membersById} canManage={canManageTasks} canUpdateTasks={canUpdateTasks} canComment={canComment} currentUserId={user?.id || ''} onUpdate={(taskId, patch) => void update(() => MarketingService.updateTask(taskId, patch), 'Tarefa atualizada.')} /> : <div className="space-y-2">{tasks.sort((a, b) => (a.due_at || '').localeCompare(b.due_at || '')).map((task) => <TaskCard key={task.id} task={task} members={membersById} canUpdate={canUpdateTasks && (canManageTasks || task.assignee_id === user?.id)} canComment={canComment} onUpdate={(patch) => void update(() => MarketingService.updateTask(task.id, patch), 'Tarefa atualizada.')} />)}{!tasks.length && <EmptyState icon={ClipboardList} title="Ainda não há tarefas" detail={canManageTasks ? 'Adicione as próximas etapas deste projeto.' : 'O gestor do projeto pode adicionar tarefas.'} />}</div>}
        </div>
        <div><h3 className="mb-2 font-semibold text-text-primary">Equipe</h3><div className="flex flex-wrap gap-2">{members.filter((member) => assignedIds.has(member.user_id) || member.user_id === project.owner_id).map((member) => <span key={member.user_id} className="rounded-full border border-border-color bg-bg-secondary px-3 py-1.5 text-xs text-text-primary">{member.nome} <span className="text-text-secondary">· {roles.find((role) => role.value === member.role)?.label}</span></span>)}{canManageTeam && <select aria-label="Atribuir integrante ao projeto" value="" onChange={(event) => { if (event.target.value) onAssign(event.target.value, true); }} className="min-h-8 rounded-full border border-dashed border-brand/50 bg-transparent px-3 text-xs text-brand"><option value="">+ Atribuir integrante</option>{members.filter((member) => member.status === 'active' && !assignedIds.has(member.user_id)).map((member) => <option key={member.user_id} value={member.user_id}>{member.nome}</option>)}</select>}</div></div>
      </div>}
      {tab === 'brief' && <BriefPanel project={project} brief={brief} canManage={canManage} editing={briefEditing} setEditing={setBriefEditing} onSave={(content, changeSummary) => void update(() => MarketingService.saveBrief(project.id, content, changeSummary), 'Nova versão do briefing salva.')} />}
      {tab === 'files' && <FilesPanel files={fileRows} canUpload={canUploadFiles} onCanDelete={(file) => canManageFiles || file.uploaded_by === user?.id} onUpload={(file, category) => void onUpload(file, category)} onDownload={(id) => void MarketingService.downloadFile(id)} onPreview={(id) => void MarketingService.downloadFile(id, 'inline')} onDelete={(id) => void update(() => MarketingService.deleteFile(id), 'Arquivo excluído do servidor.')} />}
      {tab === 'chat' && <ProjectChat project={project} canSendMessages={canSendMessages} />}
      {tab === 'reviews' && <ReviewsPanel approvals={approvals} members={membersById} tasks={tasks} canRequest={canRequestReviews} canManage={canManageReviews} onRequest={(reviewerId, taskId) => void update(() => MarketingService.requestApproval(project.id, taskId, reviewerId), 'Revisão enviada ao responsável.')} onResolve={(id, status, feedback) => void update(() => MarketingService.resolveApproval(id, status, feedback), 'Decisão de revisão registrada.')} />}
      {tab === 'history' && <HistoryPanel events={events} />}
    </div>
  </Card>;
}

function MilestonesPanel({ milestones, members, canManage, onCreate, onToggle }: { milestones: MarketingMilestone[]; members: MarketingMember[]; canManage: boolean; onCreate: (title: string, dueAt: string, assigneeId: string) => void; onToggle: (milestone: MarketingMilestone) => void }) {
  const [title, setTitle] = useState('');
  const [dueAt, setDueAt] = useState('');
  const [assigneeId, setAssigneeId] = useState('');
  return <section className="rounded-2xl border border-border-color p-4">
    <div className="mb-3 flex items-start gap-2"><Flag className="mt-0.5 h-4 w-4 text-brand" /><div><h3 className="font-semibold text-text-primary">Marcos do projeto</h3><p className="mt-0.5 text-xs text-text-secondary">Datas-chave e responsáveis, acompanhados separadamente das tarefas.</p></div></div>
    {canManage && <form onSubmit={(event) => { event.preventDefault(); if (!title.trim()) return; onCreate(title.trim(), dueAt, assigneeId); setTitle(''); setDueAt(''); setAssigneeId(''); }} className="mb-3 grid gap-2 sm:grid-cols-[minmax(0,1fr)_auto_auto_auto]">
      <input aria-label="Nome do marco" placeholder="Ex.: Aprovação da campanha" required minLength={2} maxLength={180} value={title} onChange={(event) => setTitle(event.target.value)} className="min-h-9 min-w-0 rounded-lg border border-border-color bg-bg-secondary px-3 text-xs text-text-primary" />
      <input aria-label="Prazo do marco" type="date" value={dueAt} onChange={(event) => setDueAt(event.target.value)} className="min-h-9 rounded-lg border border-border-color bg-bg-secondary px-2 text-xs text-text-primary" />
      <select aria-label="Responsável pelo marco" value={assigneeId} onChange={(event) => setAssigneeId(event.target.value)} className="min-h-9 max-w-48 rounded-lg border border-border-color bg-bg-secondary px-2 text-xs text-text-primary"><option value="">Sem responsável</option>{members.filter((member) => member.status === 'active').map((member) => <option key={member.user_id} value={member.user_id}>{member.nome}</option>)}</select>
      <Button size="sm" type="submit" leftIcon={<Plus className="h-3.5 w-3.5" />}>Adicionar</Button>
    </form>}
    <div className="space-y-2">{milestones.map((milestone) => <div key={milestone.id} className="flex items-center gap-3 rounded-xl bg-bg-secondary p-3"><button type="button" aria-label={`${milestone.completed_at ? 'Reabrir' : 'Concluir'} marco ${milestone.title}`} disabled={!canManage} onClick={() => onToggle(milestone)} className={cls('grid h-5 w-5 shrink-0 place-items-center rounded-full border', milestone.completed_at ? 'border-emerald-600 bg-emerald-600 text-white' : 'border-border-color text-transparent', canManage && 'hover:border-brand')}><Check className="h-3 w-3" /></button><div className="min-w-0 flex-1"><p className={cls('truncate text-sm font-medium', milestone.completed_at ? 'text-text-secondary line-through' : 'text-text-primary')}>{milestone.title}</p><p className="text-[11px] text-text-secondary">{milestone.due_at ? `Prazo ${localDate(milestone.due_at)}` : 'Sem prazo'}{milestone.assignee_id ? ` · ${members.find((member) => member.user_id === milestone.assignee_id)?.nome || 'Responsável'}` : ''}</p></div>{milestone.completed_at && <span className="text-[10px] font-semibold text-emerald-700">Concluído</span>}</div>)}{!milestones.length && <p className="rounded-lg bg-bg-secondary p-3 text-xs text-text-secondary">Nenhum marco definido para este projeto.</p>}</div>
  </section>;
}

function TaskCard({ task, members, canUpdate, canComment, onUpdate }: { task: MarketingTask; members: Map<string, MarketingMember>; canUpdate: boolean; canComment: boolean; onUpdate: (patch: Partial<MarketingTask>) => void }) {
  const [showComments, setShowComments] = useState(false); const [comments, setComments] = useState<Array<{ id: string; author_id: string; body: string; created_at: string }>>([]); const [comment, setComment] = useState(''); const [commentError, setCommentError] = useState('');
  const loadComments = async () => { try { setComments(await MarketingService.comments(task.id)); } catch (cause) { setCommentError(cause instanceof Error ? cause.message : 'Falha ao carregar comentários.'); } };
  const toggleComments = () => { const next = !showComments; setShowComments(next); if (next) void loadComments(); };
  const submitComment = async (event: FormEvent) => { event.preventDefault(); if (!comment.trim()) return; try { await MarketingService.addComment(task.id, comment); setComment(''); setCommentError(''); await loadComments(); } catch (cause) { setCommentError(cause instanceof Error ? cause.message : 'Falha ao enviar comentário.'); } };
  return <div className="rounded-xl border border-border-color bg-bg-primary p-3"><div className="flex flex-wrap items-start justify-between gap-2"><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-text-primary">{task.title}</p>{task.description && <p className="mt-1 whitespace-pre-wrap text-xs text-text-secondary">{task.description}</p>}<p className="mt-1.5 text-[11px] text-text-secondary">{task.assignee_id ? members.get(task.assignee_id)?.nome || 'Responsável' : 'Sem responsável'} · {localDate(task.due_at)}</p></div><div className="flex items-center gap-1.5"><PriorityPill value={task.priority} />{canUpdate ? <select aria-label={`Status da tarefa ${task.title}`} value={task.status} onChange={(event) => onUpdate({ status: event.target.value as MarketingStatus })} className="min-h-8 max-w-36 rounded-lg border border-border-color bg-bg-secondary px-1.5 text-[10px] text-text-primary">{Object.entries(statusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select> : <StatusPill value={task.status} />}</div></div><div className="mt-3 flex items-center gap-2"><div className="h-1.5 flex-1 rounded-full bg-bg-tertiary"><div className="h-1.5 rounded-full bg-brand" style={{ width: `${task.progress}%` }} /></div><span className="text-[10px] tabular-nums text-text-secondary">{task.progress}%</span>{canComment && <button type="button" onClick={toggleComments} className="inline-flex items-center gap-1 rounded-md px-2 py-1 text-[10px] text-text-secondary hover:bg-bg-tertiary"><MessageCircle className="h-3.5 w-3.5" /> Comentários</button>}</div>{canComment && showComments && <div className="mt-3 border-t border-border-color pt-3">{commentError && <p className="mb-2 text-xs text-rose-600">{commentError}</p>}<div className="max-h-44 space-y-2 overflow-y-auto">{comments.map((item) => <div key={item.id} className="rounded-lg bg-bg-secondary p-2"><p className="text-xs text-text-primary">{item.body}</p><p className="mt-1 text-[10px] text-text-secondary">{members.get(item.author_id)?.nome || 'Integrante'} · {relativeTime(item.created_at)}</p></div>)}{!comments.length && <p className="text-xs text-text-secondary">Nenhum comentário ainda.</p>}</div><form onSubmit={submitComment} className="mt-2 flex gap-2"><input value={comment} onChange={(event) => setComment(event.target.value)} maxLength={10000} placeholder="Escreva um comentário…" className="min-h-9 min-w-0 flex-1 rounded-lg border border-border-color bg-bg-secondary px-3 text-xs text-text-primary" /><Button size="sm" type="submit" aria-label="Enviar comentário" leftIcon={<Send className="h-3.5 w-3.5" />}>Enviar</Button></form></div>}</div>;
}

function BriefPanel({ project, brief, canManage, editing, setEditing, onSave }: { project: MarketingProject; brief: Record<string, unknown> | null; canManage: boolean; editing: boolean; setEditing: (value: boolean) => void; onSave: (content: Record<string, unknown>, summary: string) => void }) {
  const value = (key: string) => typeof brief?.[key] === 'string' ? brief[key] as string : '';
  const [draft, setDraft] = useState({ context: value('context'), audience: value('audience'), tone: value('tone'), channels: value('channels'), deliverables: value('deliverables'), references: value('references'), constraints: value('constraints') });
  useEffect(() => { setDraft({ context: value('context'), audience: value('audience'), tone: value('tone'), channels: value('channels'), deliverables: value('deliverables'), references: value('references'), constraints: value('constraints') }); /* latest version changes */ }, [brief]);
  const fields: Array<[keyof typeof draft, string]> = [['context','Contexto e objetivo'],['audience','Público-alvo'],['tone','Posicionamento e tom de voz'],['channels','Canais e formatos'],['deliverables','Entregáveis e critérios de aceite'],['references','Referências e materiais'],['constraints','Restrições e informações obrigatórias']];
  return <div><div className="mb-4 flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-semibold text-text-primary">Briefing do projeto</h3><p className="mt-1 text-xs text-text-secondary">Cada salvamento cria uma versão e mantém as anteriores.</p></div>{canManage && !editing && <Button size="sm" variant="outline" onClick={() => setEditing(true)}>Editar briefing</Button>}</div>{editing ? <form onSubmit={(event) => { event.preventDefault(); onSave(draft, 'Atualização de briefing'); setEditing(false); }} className="grid gap-3 md:grid-cols-2">{fields.map(([key,label]) => <label key={key} className="grid gap-1.5 text-xs font-medium text-text-secondary">{label}<textarea value={draft[key]} onChange={(event) => setDraft((current) => ({ ...current, [key]: event.target.value }))} rows={3} maxLength={5000} className="rounded-xl border border-border-color bg-bg-secondary p-3 text-sm text-text-primary outline-none focus:ring-2 focus:ring-brand/50" /></label>)}<div className="flex gap-2 md:col-span-2"><Button type="submit">Salvar nova versão</Button><Button type="button" variant="outline" onClick={() => setEditing(false)}>Cancelar</Button></div></form> : <div className="grid gap-3 md:grid-cols-2">{fields.map(([key,label]) => <div key={key} className="rounded-xl bg-bg-secondary p-4"><h4 className="text-xs font-semibold text-text-secondary">{label}</h4><p className="mt-2 whitespace-pre-wrap text-sm text-text-primary">{value(key) || (key === 'context' ? project.objective : '') || 'Não informado'}</p></div>)}</div>}{brief && <p className="mt-3 text-[11px] text-text-secondary">Versão atual do briefing: v{String(brief.version || '1')}</p>}</div>;
}

function FilesPanel({ files, canUpload, onCanDelete, onUpload, onDownload, onPreview, onDelete }: { files: Array<Record<string, any>>; canUpload: boolean; onCanDelete: (file: Record<string, any>) => boolean; onUpload: (file: File, category: string) => void; onDownload: (id: string) => void; onPreview: (id: string) => void; onDelete: (id: string) => void }) {
  const [category, setCategory] = useState('entrega');
  return <div><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-semibold text-text-primary">Arquivos do projeto</h3><p className="mt-1 text-xs text-text-secondary">Os anexos ficam em uma pasta privada no servidor da hospedagem, com acesso validado por projeto.</p></div>{canUpload && <div className="flex items-center gap-2"><select aria-label="Categoria do arquivo" value={category} onChange={(event) => setCategory(event.target.value)} className="min-h-9 rounded-lg border border-border-color bg-bg-secondary px-2 text-xs text-text-primary"><option value="briefing">Briefing</option><option value="referencia">Referência</option><option value="entrega">Entrega</option><option value="documento">Documento</option><option value="outro">Outro</option></select><label className="inline-flex min-h-9 cursor-pointer items-center gap-2 rounded-lg bg-brand px-3 text-xs font-semibold text-[#1c1008] hover:bg-brand-hover"><Paperclip className="h-3.5 w-3.5" /> Enviar arquivo<input type="file" className="sr-only" onChange={(event) => { const file = event.target.files?.[0]; if (file) onUpload(file, category); event.currentTarget.value = ''; }} /></label></div>}</div><div className="space-y-2">{files.map((file) => <div key={file.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border-color p-3"><div className="flex min-w-0 items-center gap-3"><span className="rounded-lg bg-brand/10 p-2 text-brand"><FileText className="h-4 w-4" /></span><div className="min-w-0"><p className="truncate text-sm font-semibold text-text-primary">{file.original_name}</p><p className="text-[11px] text-text-secondary">{file.content_type} · {(Number(file.size_bytes) / 1024 / 1024).toFixed(2)} MB · v{file.version}</p></div></div><div className="flex items-center gap-1"><Button size="sm" variant="outline" onClick={() => onPreview(file.id)}>Visualizar</Button><Button size="sm" variant="outline" onClick={() => onDownload(file.id)}>Baixar</Button>{onCanDelete(file) && <Button size="sm" variant="danger" onClick={() => { if (window.confirm(`Excluir “${file.original_name}” do servidor?`)) onDelete(file.id); }}>Excluir</Button>}</div></div>)}{!files.length && <EmptyState icon={FilePlus2} title="Nenhum arquivo enviado" detail="Briefings, referências e entregas do projeto ficarão organizados aqui." />}</div><p className="mt-4 rounded-lg bg-bg-secondary p-3 text-xs text-text-secondary">Limite de upload: 100 MB por arquivo. Tipos aceitos: imagens, PDF, documentos, arquivos compactados e mídia comum. O servidor remoto precisa estar configurado antes de usar esta função.</p></div>;
}

function ProjectChat({ project, canSendMessages }: { project: MarketingProject; canSendMessages: boolean }) {
  const { user } = useAuth(); const [conversationId, setConversationId] = useState(''); const [messages, setMessages] = useState<Array<{ id: string; sender_id: string; body: string; attachment_id: string | null; created_at: string }>>([]); const [draft, setDraft] = useState(''); const [error, setError] = useState(''); const [sending, setSending] = useState(false);
  const loadMessages = useCallback(async (id: string) => { try { setMessages(await MarketingService.loadMessages(id)); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Falha ao carregar chat.'); } }, []);
  useEffect(() => { let active = true; void MarketingService.openProjectChat(project.id).then((id) => { if (active) { setConversationId(id); void loadMessages(id); } }).catch((cause) => { if (active) setError(cause instanceof Error ? cause.message : 'Falha ao abrir chat do projeto.'); }); return () => { active = false; }; }, [loadMessages, project.id]);
  useEffect(() => { if (!conversationId) return; const channel = supabaseMarketingChannel(() => void loadMessages(conversationId)); return () => { channel(); }; }, [conversationId, loadMessages]);
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!canSendMessages || !draft.trim() || !conversationId) return; setSending(true); try { await MarketingService.sendMessage(conversationId, draft); setDraft(''); await loadMessages(conversationId); setError(''); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Falha ao enviar.'); } finally { setSending(false); } };
  const sendAttachment = async (file: File) => { if (!canSendMessages || !conversationId) return; setSending(true); try { const fileId = await MarketingService.uploadFile(project.id, file, 'referencia'); await MarketingService.sendMessage(conversationId, `Arquivo anexado: ${file.name}`, fileId); await loadMessages(conversationId); setError(''); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Falha ao anexar arquivo.'); } finally { setSending(false); } };
  return <div className="flex min-h-[420px] flex-col"><div className="mb-3"><h3 className="font-semibold text-text-primary">Conversa do projeto</h3><p className="mt-1 text-xs text-text-secondary">As mensagens só ficam disponíveis para integrantes com acesso ao projeto.</p></div>{error && <p role="alert" className="mb-2 rounded-lg bg-rose-500/10 px-3 py-2 text-xs text-rose-700">{error}</p>}<div className="flex-1 space-y-2 overflow-y-auto rounded-xl bg-bg-secondary p-3">{messages.map((message) => <div key={message.id} className={cls('max-w-[88%] rounded-xl p-3', message.sender_id === user?.id ? 'ml-auto bg-brand/15' : 'bg-bg-primary')}><p className="whitespace-pre-wrap break-words text-sm text-text-primary">{message.body}</p>{message.attachment_id && <button type="button" onClick={() => void MarketingService.downloadFile(message.attachment_id!, 'inline')} className="mt-2 inline-flex items-center gap-1 rounded-lg bg-bg-primary px-2 py-1 text-xs font-medium text-brand"><Paperclip className="h-3 w-3" /> Abrir anexo</button>}<p className="mt-1 text-right text-[10px] text-text-secondary">{relativeTime(message.created_at)}</p></div>)}{!messages.length && <p className="py-12 text-center text-sm text-text-secondary">Nenhuma mensagem. Use o chat para registrar decisões e dúvidas do job.</p>}</div><form onSubmit={submit} className="mt-3 flex gap-2"><label className="inline-flex min-h-11 cursor-pointer items-center justify-center rounded-xl border border-border-color px-3 text-text-secondary hover:bg-bg-tertiary" title="Anexar arquivo"><Paperclip className="h-4 w-4" /><input type="file" className="sr-only" disabled={!canSendMessages || !conversationId || sending} onChange={(event) => { const file = event.target.files?.[0]; if (file) void sendAttachment(file); event.currentTarget.value = ''; }} /></label><textarea aria-label="Mensagem para o projeto" value={draft} onChange={(event) => setDraft(event.target.value)} disabled={!canSendMessages} maxLength={10000} rows={2} placeholder="Escreva uma mensagem…" className="min-w-0 flex-1 resize-y rounded-xl border border-border-color bg-bg-secondary p-3 text-sm text-text-primary" /><Button type="submit" loading={sending} disabled={!canSendMessages || !conversationId || !draft.trim()} leftIcon={<Send className="h-4 w-4" />}>Enviar</Button></form></div>;
}

function supabaseMarketingChannel(onChange: () => void) {
  // Reuse the central channel manager so this component does not own a second Realtime client.
  return MarketingService.subscribe(onChange);
}

function TaskCalendar({ tasks, members, canManage, canUpdateTasks, canComment, currentUserId, onUpdate }: { tasks: MarketingTask[]; members: Map<string, MarketingMember>; canManage: boolean; canUpdateTasks: boolean; canComment: boolean; currentUserId: string; onUpdate: (taskId: string, patch: Partial<MarketingTask>) => void }) {
  const groups = new Map<string, MarketingTask[]>();
  tasks.forEach((task) => { const key = task.due_at ? task.due_at.slice(0, 10) : 'sem-prazo'; groups.set(key, [...(groups.get(key) || []), task]); });
  const ordered = [...groups.entries()].sort(([a],[b]) => a === 'sem-prazo' ? 1 : b === 'sem-prazo' ? -1 : a.localeCompare(b));
  return <div className="space-y-3">{ordered.map(([date, rows]) => <section key={date} className="rounded-xl border border-border-color bg-bg-secondary p-3"><div className="mb-2 flex items-center gap-2"><CalendarDays className="h-4 w-4 text-brand" /><h4 className="text-sm font-semibold text-text-primary">{date === 'sem-prazo' ? 'Sem prazo definido' : localDate(date)}</h4><span className="rounded-full bg-bg-primary px-2 py-0.5 text-[10px] text-text-secondary">{rows.length}</span></div><div className="grid gap-2 md:grid-cols-2">{rows.map((task) => <TaskCard key={task.id} task={task} members={members} canUpdate={canUpdateTasks && (canManage || task.assignee_id === currentUserId)} canComment={canComment} onUpdate={(patch) => onUpdate(task.id, patch)} />)}</div></section>)}{!tasks.length && <EmptyState icon={CalendarDays} title="Sem tarefas no cronograma" detail="Ao adicionar prazos, as tarefas ficarão agrupadas por data." />}</div>;
}

function ReviewsPanel({ approvals, members, tasks, canRequest, canManage, onRequest, onResolve }: { approvals: Array<Record<string, any>>; members: Map<string, MarketingMember>; tasks: MarketingTask[]; canRequest: boolean; canManage: boolean; onRequest: (reviewerId: string, taskId: string | null) => void; onResolve: (id: string, status: 'approved' | 'changes_requested', feedback: string) => void }) {
  const [taskId, setTaskId] = useState(''); const [reviewer, setReviewer] = useState(''); const [feedback, setFeedback] = useState('');
  const reviewers = Array.from(members.values()).filter((member) => member.status === 'active' && (['admin','gestor'].includes(member.role) || member.permission_overrides?.['reviews.manage'] === true));
  return <div><div className="mb-4"><h3 className="font-semibold text-text-primary">Revisões e aprovações</h3><p className="mt-1 text-xs text-text-secondary">Decisões e justificativas permanecem registradas no projeto.</p></div>{canRequest && <div className="mb-4 grid gap-2 rounded-xl bg-bg-secondary p-3 sm:grid-cols-[1fr_1fr_auto]"><select aria-label="Tarefa para revisão" value={taskId} onChange={(event) => setTaskId(event.target.value)} className="min-h-10 rounded-lg border border-border-color bg-bg-primary px-2 text-xs text-text-primary"><option value="">Selecione uma tarefa</option>{tasks.map((task) => <option key={task.id} value={task.id}>{task.title}</option>)}</select><select aria-label="Revisor" value={reviewer} onChange={(event) => setReviewer(event.target.value)} className="min-h-10 rounded-lg border border-border-color bg-bg-primary px-2 text-xs text-text-primary"><option value="">Selecione o revisor</option>{reviewers.map((member) => <option key={member.user_id} value={member.user_id}>{member.nome}</option>)}</select><Button size="sm" disabled={!taskId || !reviewer} onClick={() => onRequest(reviewer, taskId)}>Solicitar revisão</Button></div>}<div className="space-y-2">{approvals.map((item) => <div key={item.id} className="rounded-xl border border-border-color p-3"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-sm font-semibold text-text-primary">{tasks.find((task) => task.id === item.task_id)?.title || 'Entrega do projeto'}</p><p className="mt-1 text-xs text-text-secondary">Solicitado por {members.get(item.requested_by)?.nome || 'integrante'} · revisor {members.get(item.reviewer_id)?.nome || 'integrante'}</p></div><span className={cls('rounded-full px-2.5 py-1 text-[11px] font-semibold', item.status === 'pending' ? 'bg-amber-500/10 text-amber-700' : item.status === 'approved' ? 'bg-emerald-500/10 text-emerald-700' : 'bg-rose-500/10 text-rose-700')}>{item.status === 'pending' ? 'Pendente' : item.status === 'approved' ? 'Aprovado' : 'Ajustes solicitados'}</span></div>{item.feedback && <p className="mt-2 whitespace-pre-wrap rounded-lg bg-bg-secondary p-2 text-sm text-text-primary">{item.feedback}</p>}{canManage && item.status === 'pending' && <div className="mt-3 flex flex-wrap gap-2"><input value={feedback} onChange={(event) => setFeedback(event.target.value)} placeholder="Comentário de revisão" className="min-h-9 min-w-48 flex-1 rounded-lg border border-border-color bg-bg-secondary px-3 text-xs text-text-primary" /><Button size="sm" onClick={() => onResolve(item.id, 'approved', feedback)}>Aprovar</Button><Button size="sm" variant="outline" onClick={() => onResolve(item.id, 'changes_requested', feedback)}>Solicitar ajustes</Button></div>}</div>)}{!approvals.length && <EmptyState icon={CheckCheck} title="Sem revisões pendentes" detail="Solicite uma revisão quando uma entrega estiver pronta." />}</div></div>;
}

function HistoryPanel({ events }: { events: Array<Record<string, any>> }) {
  return <div><h3 className="mb-4 font-semibold text-text-primary">Histórico do projeto</h3><div className="relative space-y-3 before:absolute before:bottom-2 before:left-[9px] before:top-2 before:w-px before:bg-border-color">{events.map((event) => <div key={event.id} className="relative pl-7"><span className="absolute left-1 top-1.5 h-2.5 w-2.5 rounded-full bg-brand ring-4 ring-bg-primary" /><p className="text-sm text-text-primary">{event.summary}</p><p className="mt-0.5 text-[11px] text-text-secondary">{relativeTime(event.created_at)}</p></div>)}{!events.length && <EmptyState icon={Activity} title="O projeto ainda não tem histórico" detail="As alterações registradas aparecerão automaticamente nesta linha do tempo." />}</div></div>;
}

function TasksPanel({ tasks, projects, members, canManage, canUpdateTasks, canComment, canRequestReviews, currentUserId, onUpdate, onComment, onReview }: { tasks: MarketingTask[]; projects: MarketingProject[]; members: MarketingMember[]; canManage: boolean; canUpdateTasks: boolean; canComment: boolean; canRequestReviews: boolean; currentUserId: string; onUpdate: (id: string, patch: Partial<MarketingTask>) => void; onComment: (id: string, body: string) => void; onReview: (projectId: string, taskId: string, reviewerId: string) => void }) {
  const [filter, setFilter] = useState('minhas'); const [reviewers, setReviewers] = useState<Record<string, string>>({});
  const scoped = tasks.filter((task) => filter === 'minhas' ? task.assignee_id === currentUserId : filter === 'atrasadas' ? isLate(task.due_at, task.status) : filter === 'revisao' ? ['em_revisao','aguardando_aprovacao'].includes(task.status) : true);
  const memberMap = new Map(members.map((member) => [member.user_id, member]));
  return <div><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-semibold text-text-primary">Tarefas e entregas</h2><p className="text-xs text-text-secondary">Atualizadas em tempo real conforme atribuição e andamento.</p></div><FormSelect label="Exibir" value={filter} onChange={(event) => setFilter(event.target.value)} className="min-w-40"><option value="minhas">Minhas tarefas</option><option value="atrasadas">Atrasadas</option><option value="revisao">Em revisão</option><option value="todas">Todas as autorizadas</option></FormSelect></div><div className="space-y-3">{scoped.map((task) => <Card key={task.id}><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0 flex-1"><p className="font-semibold text-text-primary">{task.title}</p><p className="mt-1 text-xs text-text-secondary">{projects.find((project) => project.id === task.project_id)?.name || 'Projeto'} · {memberMap.get(task.assignee_id || '')?.nome || 'Sem responsável'} · {localDate(task.due_at)}</p>{task.description && <p className="mt-2 whitespace-pre-wrap text-sm text-text-secondary">{task.description}</p>}</div><div className="flex items-center gap-2"><PriorityPill value={task.priority} /><StatusPill value={task.status} /></div></div><div className="mt-4 flex flex-wrap items-center gap-2">{canUpdateTasks && (canManage || task.assignee_id === currentUserId) ? <select aria-label={`Atualizar status de ${task.title}`} value={task.status} onChange={(event) => onUpdate(task.id, { status: event.target.value as MarketingStatus })} className="min-h-9 rounded-lg border border-border-color bg-bg-secondary px-2 text-xs text-text-primary">{Object.entries(statusLabels).map(([value,label]) => <option key={value} value={value}>{label}</option>)}</select> : null}{canComment && <><input aria-label={`Comentário em ${task.title}`} id={`comment-${task.id}`} placeholder="Adicionar comentário" className="min-h-9 min-w-44 flex-1 rounded-lg border border-border-color bg-bg-secondary px-3 text-xs text-text-primary" /><Button size="sm" variant="outline" onClick={() => { const el = document.getElementById(`comment-${task.id}`) as HTMLInputElement | null; const text = el?.value.trim(); if (text) { onComment(task.id, text); if (el) el.value = ''; } }}>Comentar</Button></>}{canRequestReviews && <><select aria-label={`Selecionar revisor da tarefa ${task.title}`} value={reviewers[task.id] || ''} onChange={(event) => setReviewers((current) => ({ ...current, [task.id]: event.target.value }))} className="min-h-9 rounded-lg border border-border-color bg-bg-secondary px-2 text-xs text-text-primary"><option value="">Revisor</option>{members.filter((member) => member.status === 'active' && (['admin','gestor'].includes(member.role) || member.permission_overrides?.['reviews.manage'] === true)).map((member) => <option key={member.user_id} value={member.user_id}>{member.nome}</option>)}</select><Button size="sm" onClick={() => { const reviewerId = reviewers[task.id]; if (reviewerId) onReview(task.project_id, task.id, reviewerId); }}>Enviar para revisão</Button></>}</div></Card>)}{!scoped.length && <Card><EmptyState icon={ClipboardList} title="Nenhuma tarefa neste filtro" detail="Ajuste os filtros ou aguarde novas atribuições." /></Card>}</div></div>;
}

function InboxPanel({ notifications, onMarkRead }: { notifications: MarketingWorkspaceData['notifications']; onMarkRead: (id: string) => void }) {
  const unread = notifications.filter((item) => !item.read_at).length;
  return <div><div className="mb-4 flex items-center justify-between"><div><h2 className="text-lg font-semibold text-text-primary">Caixa de entrada operacional</h2><p className="text-xs text-text-secondary">Atribuições, mensagens, prazos e revisões para você.</p></div><span className="rounded-full bg-brand/10 px-3 py-1 text-xs font-semibold text-brand">{unread} não lidas</span></div><div className="space-y-2">{notifications.map((item) => <div key={item.id} className={cls('flex items-start gap-3 rounded-xl border p-4', item.read_at ? 'border-border-color bg-bg-primary' : 'border-brand/40 bg-brand/5')}><Bell className="mt-0.5 h-4 w-4 shrink-0 text-brand" /><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-text-primary">{item.title}</p><p className="mt-1 whitespace-pre-wrap text-sm text-text-secondary">{item.body}</p><p className="mt-2 text-[10px] text-text-secondary">{relativeTime(item.created_at)}</p></div>{!item.read_at && <Button size="sm" variant="outline" onClick={() => onMarkRead(item.id)}>Marcar lida</Button>}</div>)}{!notifications.length && <Card><EmptyState icon={Inbox} title="Caixa de entrada vazia" detail="As notificações dos projetos aparecerão aqui." /></Card>}</div></div>;
}

function TeamPanel({ members, currentUserId, onSave, onInvite }: { members: MarketingMember[]; currentUserId: string; onSave: (userId: string, nome: string, email: string, role: MarketingMember['role'], active: boolean, overrides?: Record<string, boolean>) => void; onInvite: (nome: string, email: string, role: MarketingMember['role']) => void }) {
  const [directory, setDirectory] = useState<Array<{ id: string; nome: string; email: string }>>([]); const [error, setError] = useState(''); const [selectedId, setSelectedId] = useState(''); const [role, setRole] = useState<MarketingMember['role']>('designer'); const [inviteName, setInviteName] = useState(''); const [inviteEmail, setInviteEmail] = useState(''); const [inviteRole, setInviteRole] = useState<MarketingMember['role']>('designer'); const [loadingDirectory, setLoadingDirectory] = useState(true);
  useEffect(() => { void MarketingService.directory().then(setDirectory).catch((cause) => setError(cause instanceof Error ? cause.message : 'Falha ao consultar usuários.')).finally(() => setLoadingDirectory(false)); }, []);
  const notAdded = directory.filter((profile) => !members.some((member) => member.user_id === profile.id));
  return <div><div className="mb-4"><h2 className="text-lg font-semibold text-text-primary">Equipe autorizada</h2><p className="text-xs text-text-secondary">Convide profissionais para criar a conta e habilite contas já cadastradas no GrowMoney. Só integrantes ativos acessam projetos de Marketing.</p></div>{error && <p role="alert" className="mb-3 rounded-lg bg-rose-500/10 p-3 text-sm text-rose-700">{error}</p>}<form onSubmit={(event) => { event.preventDefault(); onInvite(inviteName.trim(), inviteEmail.trim(), inviteRole); }} className="mb-4 grid gap-3 rounded-2xl border border-brand/30 bg-bg-primary p-4 sm:grid-cols-2"><div className="sm:col-span-2"><h3 className="flex items-center gap-2 text-sm font-semibold text-text-primary"><Mail className="h-4 w-4 text-brand" />Convidar novo profissional</h3><p className="mt-1 text-xs text-text-secondary">O convite será enviado por e-mail. A pessoa confirma o endereço e define a própria senha.</p></div><FormField label="Nome" value={inviteName} onChange={(event) => setInviteName(event.target.value)} required minLength={2} maxLength={120} /><FormField label="E-mail" type="email" value={inviteEmail} onChange={(event) => setInviteEmail(event.target.value)} required maxLength={254} /><FormSelect label="Função na equipe" value={inviteRole} onChange={(event) => setInviteRole(event.target.value as MarketingMember['role'])}>{roles.filter((item) => item.value !== 'admin').map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</FormSelect><div className="flex items-end"><Button type="submit" leftIcon={<Mail className="h-4 w-4" />}>Enviar convite</Button></div></form><form onSubmit={(event) => { event.preventDefault(); const profile = directory.find((item) => item.id === selectedId); if (profile) onSave(profile.id, profile.nome || profile.email, profile.email, role, true); }} className="mb-4 grid gap-2 rounded-2xl border border-border-color bg-bg-primary p-4 sm:grid-cols-[1fr_1fr_auto]"><FormSelect label="Autorizar usuário já cadastrado" value={selectedId} disabled={loadingDirectory} onChange={(event) => setSelectedId(event.target.value)}><option value="">{loadingDirectory ? 'Carregando…' : 'Escolha um usuário existente'}</option>{notAdded.map((profile) => <option key={profile.id} value={profile.id}>{profile.nome || profile.email} · {profile.email}</option>)}</FormSelect><FormSelect label="Função na equipe" value={role} onChange={(event) => setRole(event.target.value as MarketingMember['role'])}>{roles.filter((item) => item.value !== 'admin').map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</FormSelect><div className="flex items-end"><Button type="submit" disabled={!selectedId} leftIcon={<Plus className="h-4 w-4" />}>Autorizar integrante</Button></div></form><div className="grid gap-3 md:grid-cols-2">{members.map((member) => <MemberCard key={member.user_id} member={member} currentUserId={currentUserId} onSave={onSave} />)}{!members.length && <EmptyState icon={Users} title="Nenhum integrante cadastrado" detail="Convide profissionais ou autorize usuários já existentes." />}</div></div>;
}

const permissionOptions = [
  { key: 'projects.manage', label: 'Gerenciar projetos', default: (role: MarketingMember['role']) => ['admin','gestor'].includes(role) },
  { key: 'team.manage', label: 'Gerenciar integrantes', default: (role: MarketingMember['role']) => ['admin','gestor'].includes(role) },
  { key: 'tasks.manage', label: 'Atribuir e administrar tarefas', default: (role: MarketingMember['role']) => ['admin','gestor'].includes(role) },
  { key: 'tasks.update', label: 'Atualizar tarefas atribuídas', default: () => true },
  { key: 'files.manage', label: 'Excluir arquivos do projeto', default: (role: MarketingMember['role']) => ['admin','gestor'].includes(role) },
  { key: 'files.upload', label: 'Enviar arquivos', default: () => true },
  { key: 'comments.create', label: 'Comentar em tarefas', default: () => true },
  { key: 'reviews.request', label: 'Solicitar revisões', default: () => true },
  { key: 'chat.send', label: 'Enviar mensagens', default: () => true },
  { key: 'reports.view', label: 'Visualizar relatórios', default: () => true },
];

function MemberCard({ member, currentUserId, onSave }: { member: MarketingMember; currentUserId: string; onSave: (userId: string, nome: string, email: string, role: MarketingMember['role'], active: boolean, overrides?: Record<string, boolean>) => void }) {
  const overrides = member.permission_overrides || {};
  if (member.user_id === currentUserId) return <article className="rounded-2xl border border-border-color bg-bg-primary p-4"><p className="truncate text-sm font-semibold text-text-primary">{member.nome} (você)</p><p className="truncate text-xs text-text-secondary">{member.email}</p><p className="mt-1 text-[10px] uppercase tracking-wide text-brand">{roles.find((item) => item.value === member.role)?.label || member.role} · autoedição de permissões bloqueada</p></article>;
  const saveOverrides = (next: Record<string, boolean>) => onSave(member.user_id, member.nome, member.email, member.role, member.status === 'active', next);
  return <article className="rounded-2xl border border-border-color bg-bg-primary p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div className="min-w-0"><p className="truncate text-sm font-semibold text-text-primary">{member.nome}</p><p className="truncate text-xs text-text-secondary">{member.email}</p><p className="mt-1 text-[10px] uppercase tracking-wide text-brand">{roles.find((item) => item.value === member.role)?.label || member.role}</p></div><div className="flex items-center gap-2"><span className={cls('rounded-full px-2.5 py-1 text-[10px] font-semibold', member.status === 'active' ? 'bg-emerald-500/10 text-emerald-700' : 'bg-bg-tertiary text-text-secondary')}>{member.status === 'active' ? 'Ativo' : 'Inativo'}</span>{member.role === 'admin' ? <span className="text-xs text-text-secondary">Perfil global</span> : <select aria-label={`Alterar função de ${member.nome}`} value={member.role} onChange={(event) => onSave(member.user_id, member.nome, member.email, event.target.value as MarketingMember['role'], member.status === 'active', overrides)} className="min-h-9 max-w-44 rounded-lg border border-border-color bg-bg-secondary px-2 text-xs text-text-primary">{roles.filter((item) => item.value !== 'admin').map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select>}</div></div><details className="mt-3 border-t border-border-color pt-3"><summary className="cursor-pointer text-xs font-semibold text-text-secondary">Permissões deste integrante</summary><div className="mt-3 grid gap-2 sm:grid-cols-2">{permissionOptions.map((permission) => <label key={permission.key} className="flex items-center justify-between gap-2 rounded-lg bg-bg-secondary px-3 py-2 text-xs text-text-primary"><span>{permission.label}<span className="ml-1 text-[10px] text-text-secondary">(padrão: {permission.default(member.role) ? 'permitido' : 'negado'})</span></span><select aria-label={`${permission.label} para ${member.nome}`} value={Object.prototype.hasOwnProperty.call(overrides, permission.key) ? String(overrides[permission.key]) : ''} onChange={(event) => { const next = { ...overrides }; if (event.target.value === '') delete next[permission.key]; else next[permission.key] = event.target.value === 'true'; saveOverrides(next); }} className="min-h-8 rounded-md border border-border-color bg-bg-primary px-2 text-[10px] text-text-primary"><option value="">Padrão</option><option value="true">Permitir</option><option value="false">Negar</option></select></label>)}</div><button type="button" onClick={() => onSave(member.user_id, member.nome, member.email, member.role, member.status !== 'active', overrides)} className="mt-3 min-h-9 rounded-lg border border-border-color px-3 text-xs font-semibold text-text-secondary hover:bg-bg-tertiary">{member.status === 'active' ? 'Desativar acesso' : 'Reativar acesso'}</button></details></article>;
}

function ReportsPanel({ data, tasks }: { data: MarketingWorkspaceData; tasks: MarketingTask[] }) {
  const [period, setPeriod] = useState('30'); const [projectId, setProjectId] = useState('todos'); const start = new Date(); start.setDate(start.getDate() - Number(period));
  const scoped = tasks.filter((task) => new Date(task.created_at) >= start && (projectId === 'todos' || task.project_id === projectId));
  const completed = scoped.filter((task) => task.status === 'concluido'); const timely = completed.filter((task) => !isLate(task.due_at, task.status));
  const byMember = data.members.map((member) => ({ member, assigned: scoped.filter((task) => task.assignee_id === member.user_id).length, completed: completed.filter((task) => task.assignee_id === member.user_id).length })).filter((row) => row.assigned > 0);
  const maxCount = Math.max(...byMember.map((row) => row.assigned), 1);
  return <div><div className="mb-4 flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-lg font-semibold text-text-primary">Indicadores operacionais</h2><p className="text-xs text-text-secondary">Os indicadores descrevem fluxo e carga; não substituem contexto ou avaliação humana.</p></div><div className="flex gap-2"><FormSelect label="Período" value={period} onChange={(event) => setPeriod(event.target.value)}><option value="7">7 dias</option><option value="30">30 dias</option><option value="90">90 dias</option><option value="365">12 meses</option></FormSelect><FormSelect label="Projeto" value={projectId} onChange={(event) => setProjectId(event.target.value)}><option value="todos">Todos</option>{data.projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</FormSelect></div></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[{ label: 'Projetos ativos', value: data.projects.filter((item) => !['concluido','cancelado'].includes(item.status)).length }, { label: 'Tarefas no período', value: scoped.length }, { label: 'Concluídas no prazo', value: timely.length }, { label: 'Em revisão', value: scoped.filter((task) => ['em_revisao','aguardando_aprovacao'].includes(task.status)).length }].map((item) => <Card key={item.label}><p className="text-xs text-text-secondary">{item.label}</p><p className="mt-2 text-3xl font-bold text-text-primary">{item.value}</p></Card>)}</div><Card className="mt-4" header={<h3 className="font-semibold text-text-primary">Distribuição de trabalho no período</h3>}><div className="space-y-4">{byMember.map(({ member, assigned, completed: done }) => <div key={member.user_id}><div className="mb-1 flex justify-between text-xs"><span className="font-medium text-text-primary">{member.nome}</span><span className="text-text-secondary">{assigned} atribuídas · {done} concluídas</span></div><div className="h-2 rounded-full bg-bg-tertiary"><div className="h-2 rounded-full bg-brand" style={{ width: `${Math.max(6, assigned / maxCount * 100)}%` }} /></div></div>)}{!byMember.length && <p className="text-sm text-text-secondary">Ainda não há dados suficientes para este recorte.</p>}</div></Card></div>;
}

function NewProjectModal({ members, onClose, onSubmit }: { members: MarketingMember[]; onClose: () => void; onSubmit: (input: Pick<MarketingProject, 'name' | 'client_label' | 'objective' | 'scope' | 'description' | 'status' | 'priority' | 'starts_at' | 'due_at'>, memberIds: string[]) => void }) {
  const [name, setName] = useState(''); const [client, setClient] = useState(''); const [objective, setObjective] = useState(''); const [scope, setScope] = useState(''); const [description, setDescription] = useState(''); const [priority, setPriority] = useState<MarketingPriority>('normal'); const [due, setDue] = useState(''); const [selectedMembers, setSelectedMembers] = useState<string[]>([]);
  return <Modal title="Novo projeto de marketing" onClose={onClose}><form onSubmit={(event) => { event.preventDefault(); onSubmit({ name: name.trim(), client_label: client.trim() || null, objective: objective.trim(), scope: scope.trim(), description: description.trim(), status: 'briefing_pendente', priority, starts_at: new Date().toISOString().slice(0,10), due_at: due || null }, selectedMembers); }} className="grid gap-3 sm:grid-cols-2"><FormField label="Nome do projeto" value={name} onChange={(event) => setName(event.target.value)} required minLength={2} maxLength={180} className="sm:col-span-2" /><FormField label="Cliente ou marca" value={client} onChange={(event) => setClient(event.target.value)} maxLength={180} /><FormSelect label="Prioridade" value={priority} onChange={(event) => setPriority(event.target.value as MarketingPriority)}>{Object.entries(priorityLabels).map(([value,label]) => <option key={value} value={value}>{label}</option>)}</FormSelect><FormField label="Prazo final" type="date" value={due} onChange={(event) => setDue(event.target.value)} /><label className="grid gap-1.5 text-xs font-medium text-text-secondary sm:col-span-2">Objetivo<textarea rows={2} value={objective} onChange={(event) => setObjective(event.target.value)} className="rounded-xl border border-border-color bg-bg-secondary p-3 text-sm text-text-primary" /></label><label className="grid gap-1.5 text-xs font-medium text-text-secondary sm:col-span-2">Escopo e entregáveis<textarea rows={3} value={scope} onChange={(event) => setScope(event.target.value)} className="rounded-xl border border-border-color bg-bg-secondary p-3 text-sm text-text-primary" /></label><label className="grid gap-1.5 text-xs font-medium text-text-secondary sm:col-span-2">Descrição e critérios de aceite<textarea rows={2} value={description} onChange={(event) => setDescription(event.target.value)} className="rounded-xl border border-border-color bg-bg-secondary p-3 text-sm text-text-primary" /></label><fieldset className="grid gap-2 sm:col-span-2"><legend className="mb-1 text-xs font-medium text-text-secondary">Atribuir integrantes</legend><div className="flex flex-wrap gap-2">{members.map((member) => <label key={member.user_id} className="inline-flex cursor-pointer items-center gap-2 rounded-full border border-border-color px-3 py-2 text-xs text-text-primary"><input type="checkbox" checked={selectedMembers.includes(member.user_id)} onChange={(event) => setSelectedMembers((current) => event.target.checked ? [...current, member.user_id] : current.filter((id) => id !== member.user_id))} />{member.nome}</label>)}</div></fieldset><ModalActions onClose={onClose} submitLabel="Criar projeto" /></form></Modal>;
}

function NewTaskModal({ project, members, onClose, onSubmit }: { project: MarketingProject; members: MarketingMember[]; onClose: () => void; onSubmit: (input: Pick<MarketingTask, 'project_id' | 'title' | 'description' | 'status' | 'priority' | 'assignee_id' | 'due_at'>) => void }) {
  const [title, setTitle] = useState(''); const [description, setDescription] = useState(''); const [assignee, setAssignee] = useState(''); const [due, setDue] = useState(''); const [priority, setPriority] = useState<MarketingPriority>('normal');
  return <Modal title="Nova tarefa" onClose={onClose}><form onSubmit={(event) => { event.preventDefault(); onSubmit({ project_id: project.id, title: title.trim(), description: description.trim(), status: 'nao_iniciado', priority, assignee_id: assignee || null, due_at: due || null }); }} className="grid gap-3 sm:grid-cols-2"><p className="text-xs text-text-secondary sm:col-span-2">Projeto: <strong className="text-text-primary">{project.name}</strong></p><FormField label="Título" value={title} onChange={(event) => setTitle(event.target.value)} required minLength={2} maxLength={180} className="sm:col-span-2" /><label className="grid gap-1.5 text-xs font-medium text-text-secondary sm:col-span-2">Descrição<textarea rows={3} value={description} onChange={(event) => setDescription(event.target.value)} className="rounded-xl border border-border-color bg-bg-secondary p-3 text-sm text-text-primary" /></label><FormSelect label="Responsável" value={assignee} onChange={(event) => setAssignee(event.target.value)}><option value="">Sem responsável</option>{members.map((member) => <option key={member.user_id} value={member.user_id}>{member.nome}</option>)}</FormSelect><FormSelect label="Prioridade" value={priority} onChange={(event) => setPriority(event.target.value as MarketingPriority)}>{Object.entries(priorityLabels).map(([value,label]) => <option key={value} value={value}>{label}</option>)}</FormSelect><FormField label="Prazo" type="date" value={due} onChange={(event) => setDue(event.target.value)} /><ModalActions onClose={onClose} submitLabel="Criar tarefa" /></form></Modal>;
}

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) { return <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/55 p-3 sm:p-6" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section role="dialog" aria-modal="true" aria-labelledby="marketing-modal-title" className="max-h-[92dvh] w-full max-w-2xl overflow-y-auto rounded-2xl border border-border-color bg-bg-primary p-4 shadow-2xl sm:p-6"><div className="mb-4 flex items-center justify-between"><h2 id="marketing-modal-title" className="text-lg font-bold text-text-primary">{title}</h2><button type="button" aria-label="Fechar" onClick={onClose} className="rounded-lg p-2 text-text-secondary hover:bg-bg-tertiary"><X className="h-4 w-4" /></button></div>{children}</section></div>; }
function ModalActions({ onClose, submitLabel }: { onClose: () => void; submitLabel: string }) { return <div className="mt-2 flex justify-end gap-2 sm:col-span-2"><Button type="button" variant="outline" onClick={onClose}>Cancelar</Button><Button type="submit">{submitLabel}</Button></div>; }
function EmptyState({ icon: Icon, title, detail }: { icon: typeof Activity; title: string; detail: string }) { return <div className="flex flex-col items-center justify-center rounded-xl border border-dashed border-border-color px-5 py-10 text-center"><Icon className="h-7 w-7 text-brand" /><p className="mt-3 text-sm font-semibold text-text-primary">{title}</p><p className="mt-1 max-w-sm text-xs text-text-secondary">{detail}</p></div>; }

